  const CREATE_LOOSE_EN = /\b(?:write|make)\s+(?:up\s+)?(?:a|an|the)\s+(?:short\s+|new\s+)?(?:\w+\s+){0,2}(?:google\s+doc|document|spreadsheet|sheet|deck|doc)\b/i;
  const SHARE_EN = /\b(?:send|share|attach|forward|email|pass(?:\s+it)?\s+along)\b/i;
