    // The word call there is not a reminder to phone someone.
    const callBody = untimedSrc
      .replace(/\bfollowing up on (?:our|the|that) call\b/ig, ' ')
      .replace(/\bper our call\b/ig, ' ')
      .replace(/\bper our chat\b/ig, ' ');
