    decision: ['Log decision', 'לתעד החלטה'],
    commitment: ['Log commitment', 'לתעד התחייבות'],
    task: ['Handle this note', 'לטפל בהערה'],
    reply: ['Reply requested', 'נדרשת תשובה'],
    event: ['Meeting', 'פגישה'],
