    return (name ? 'Hi ' + name + ',' : 'Hi,') + '\n\nA quick reminder about the ' + need.label + (payer ? ' for ' + payer : '') + (amt ? ' for ' + amt : '') + (o.days ? ' (I asked ' + o.days + ' days ago)' : '') + '. Could you send it to me as a file?\n\nThanks,';
